fn timed_ask_without_answer_workflow() -> Option<vb_core::workflow::CompiledWorkflow> {
    let set_prompt = CompiledNode {
        id: vb_core::ids::StepIdx::ZERO,
        output: Some(SlotIdx::ZERO),
        next: Some(vb_core::ids::StepIdx::new(1)),
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::SetConst {
            value: ConstIdx::new(0),
        },
    };
    let set_timeout = CompiledNode {
        id: vb_core::ids::StepIdx::new(1),
        output: Some(SlotIdx::new(1)),
        next: Some(vb_core::ids::StepIdx::new(2)),
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::SetConst {
            value: ConstIdx::new(1),
        },
    };
    let ask = CompiledNode {
        id: vb_core::ids::StepIdx::new(2),
        output: None,
        next: Some(vb_core::ids::StepIdx::new(3)),
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::Ask {
            prompt: SlotIdx::ZERO,
            timeout_slot: Some(SlotIdx::new(1)),
        },
    };
    let resume = CompiledNode {
        id: vb_core::ids::StepIdx::new(3),
        output: None,
        next: Some(vb_core::ids::StepIdx::new(4)),
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::AskResume {
            answer: SlotIdx::new(2),
        },
    };
    let finish = CompiledNode {
        id: vb_core::ids::StepIdx::new(4),
        output: None,
        next: None,
        on_error: None,
        error_slot: None,
        kind: CompiledNodeKind::Finish {
            result: SlotIdx::new(2),
        },
    };
    let parts = WorkflowParts {
        semantic_source_identity: None,
        name: Box::from("timed_ask_without_answer"),
        digest: WorkflowDigest::from_bytes([5; 32]),
        nodes: Box::from([set_prompt, set_timeout, ask, resume, finish]),
        expressions: Box::from([]),
        accessors: Box::from([]),
        constants: Box::from([
            vb_core::value::ConstValue::Symbol(vb_core::ids::SymbolId::new(1)),
            vb_core::value::ConstValue::I64(10),
        ]),
        slot_count: 3,
        symbols_count: 2,
        entry: vb_core::ids::StepIdx::ZERO,
        step_names: Box::from([]),
        resource_contract: ResourceContract::DEFAULT,
        input_slots: Box::from([]),
    };
    vb_core::workflow::CompiledWorkflow::try_from_parts(parts).ok()
}

fn small_config() -> ShardConfig {
    ShardConfig {
        command_queue_capacity: 16,
        trace_capacity: 16,
        step_budget_per_tick: 4,
        max_active_runs: 4,
        policy: vb_core::policy::RuntimePolicy::Relaxed,
    }
}

fn workflow_fixture(
    workflow: Option<vb_core::workflow::CompiledWorkflow>,
    name: &'static str,
) -> Result<vb_core::workflow::CompiledWorkflow, String> {
    workflow.ok_or_else(|| {
        let mut message = name.to_owned();
        message.push_str(" fixture must build");
        message
    })
}

#[test]
fn finished_run_releases_frame_to_dimension_pool() -> Result<(), String> {
    let config = small_config();
    let mut shard = Shard::new(config);
    let workflow = workflow_fixture(finished_workflow(), "finished_workflow")?;

    assert_eq!(
        shard.enqueue(ShardCommand::Submit {
            run: super::RunId::new(1),
            workflow: workflow,
            caps: vb_core::capability::CapabilitySet::empty()
        }),
        Ok(())
    );
    assert_eq!(shard.tick(), Ok(true));

    let available = shard.frame_pools.get(&(2, 1)).map(FramePool::available);
    // Pool pre-allocated to capacity (4); finished run's frame was released back
    assert_eq!(available, Some(4));
    Ok(())
}

#[test]
fn cancelled_run_releases_frame_to_dimension_pool() -> Result<(), String> {
    let config = small_config();
    let mut shard = Shard::new(config);
    let workflow = workflow_fixture(suspended_workflow(), "suspended_workflow")?;
    let run = super::RunId::new(11);

    assert_eq!(
        shard.enqueue(ShardCommand::SubmitWithInputsAndContracts {
            run: run,
            workflow: workflow,
            caps: test_fixtures::contract_capability_for(ActionId::new(0)),
            action_contracts: test_fixtures::contracts_through(ActionId::new(0)),
            inputs: Box::from([(SlotIdx::ZERO, SlotValue::I64(0))])
        }),
        Ok(())
    );
    assert_eq!(shard.tick(), Ok(true));
    assert_eq!(
        shard.frame_pools.get(&(1, 1)).map(FramePool::available),
        // Pool pre-allocated to capacity (4); one frame in use, three available
        Some(3)
    );

    assert_eq!(
        shard.enqueue(ShardCommand::Cancel { run, reason: None }),
        Ok(())
    );
    assert_eq!(shard.tick(), Ok(true));
    assert_eq!(
        shard.frame_pools.get(&(1, 1)).map(FramePool::available),
        // After cancel, frame returned; 4 available
        Some(4)
    );
    Ok(())
}

