        }),
        Ok(())
    );
    assert_eq!(shard.tick(), Ok(true));
    let drained_before_failure = shard.trace_ring_mut().drain();
    assert_ne!(drained_before_failure.len(), 0);
    let ticket = action_ticket(run, vb_core::ids::StepIdx::ZERO);
    let failure = timeout_failure();
    assert_eq!(
